export const ESCAPE_EXCLUDE_CHARS_REGEX = /[\-\^\*\\\]]/g;
export function runValidationEngine(value, validators) {
    //If there are no validators, then it's valid!
    if (validators == null || validators.length === 0) {
        return {
            isValid: true
        };
    }
    //We are assuming that if isRequired would be the first validator.
    //If we decide there is a case where something else needs to be run first then
    //we can alter this test.
    if (validators[0].condition !== 'IS_REQUIRED_RULE' && //not required
        (value === '' || value == null)) {
        //no value
        return {
            isValid: true
        };
    }
    const context = {};
    for (const validator of validators) {
        //NOTE: validator run in the context of the validationRulesEngine
        const result = validator.execute.call(this, value, validator.condition, context);
        if (result.ignoreSubsequentValidators === true || !result.isValid) {
            return result;
        }
    }
    //If we made it here, it's valid.
    return {
        isValid: true
    };
}
//* * * * * Validator Functions * * * * *
function validateIsRequired(input, condition, context) {
    if (input == null || input.trim().length === 0) {
        return {
            isValid: false,
            errorMessage: translate('neon|required'),
            invalidRule: 'isRequired'
        };
    }
    else {
        return validResult;
    }
}
export function getIsRequiredValidator() {
    return {
        execute: validateIsRequired,
        condition: 'IS_REQUIRED_RULE'
    };
}
//by using a singleton here, we can avoid creating a brand new object every time.
const validResult = {
    isValid: true
};
//The point of this function is to not create a property on the BasicValidationRules object
//when the value is undefined, null, or ''.
//This is private. (really)
//This gets connected to an empty ValidationRules object
function setProperty(property, value, type = String) {
    let parsedValue;
    //Empty values are ignored.
    if (value == null || value === '') {
        return;
    }
    if (type === Boolean) {
        // this is here because new Boolean('false') evaluates to true
        parsedValue = value === 'true';
    }
    else if (type === Number) {
        parsedValue = type(value);
    }
    else {
        parsedValue = new type(value);
    }
    if (typeof parsedValue === 'number' && isNaN(parsedValue)) {
        return;
    }
    if (parsedValue instanceof Date && isNaN(parsedValue.getTime())) {
        return;
    }
    this[property] = parsedValue;
}
