export function getBasicTextValidationRules() {
    return {
        setProperty: setProperty
    };
}
export function getBasicNumberValidationRules() {
    return {
        setProperty: setProperty
    };
}
export function getBasicDateValidationRules() {
    return {
        setProperty: setProperty
    };
}
export function getBasicTimeValidationRules() {
    return {
        setProperty: setProperty
    };
}
//* * * * * GetValidators functions * * * * * * *
export function getRequiredOnlyValidators(isRequired) {
    const validators = [];
    if (isRequired) {
        validators.push(getIsRequiredValidator());
    }
    return validators;
}
export function getTextValidators(rules) {
    const validators = [];
    if (rules.isRequired) {
        validators.push(getIsRequiredValidator());
    }
    if (rules.maxLength != null) {
        validators.push({
            execute: validateMaxTextLength,
            condition: rules.maxLength
        });
    }
    if (rules.minLength != null) {
        validators.push({
            execute: validateMinTextLength,
            condition: rules.minLength
        });
    }
    if (rules.excludeChars != null) {
        //Escape some characters that would mess up the regex.
        // let escapedChars =  rules.excludeChars.replace('^', '\\^').replace('\]', '\\]').replace('-', '\\-');
        const escapedChars = rules.excludeChars.replace(ESCAPE_EXCLUDE_CHARS_REGEX, '\\$&');
        validators.push({
            execute: validateExcludeChars,
            condition: {
                pattern: new RegExp(`[${escapedChars}]`, 'i'),
                excludeChars: rules.excludeChars
            }
        });
    }
    if (rules.regex != null) {
        validators.push({
            execute: validateRegex,
            condition: rules.regex
        });
    }
    if (rules.isEmail) {
        validators.push({
            execute: validateEmail
        });
    }
    return validators;
}
export function getNumberValidators(rules) {
    //console.log('gettign number validators');
    const validators = [];
    if (rules.isRequired) {
        validators.push(getIsRequiredValidator());
    }
    //No if here. If it's a number, it needs to be a valid number.
    validators.push({
        execute: validateIsNumber
    });
    if (rules.isInteger) {
        validators.push({
            execute: validateIsInteger
        });
    }
    if (rules.maxValue != null && typeof rules.maxValue !== 'string') {
        validators.push({
            execute: validateMaxNumberValue,
            condition: rules.maxValue
        });
    }
    if (rules.minValue != null && typeof rules.minValue !== 'string') {
        validators.push({
            execute: validateMinNumberValue,
            condition: rules.minValue
        });
    }
    if (rules.maxValueExclusive != null && typeof rules.maxValueExclusive !== 'string') {
        validators.push({
            execute: validateMaxNumberValueExclusive,
            condition: rules.maxValueExclusive
        });
    }
    if (rules.minValueExclusive != null && typeof rules.minValueExclusive !== 'string') {
        validators.push({
            execute: validateMinNumberValueExclusive,
            condition: rules.minValueExclusive
        });
    }
    if (rules.maxLength != null) {
        validators.push({
            execute: validateMaxNumberLength,
            condition: rules.maxLength
        });
    }
    if (rules.minLength != null) {
        validators.push({
            execute: validateMinNumberLength,
            condition: rules.minLength
        });
    }
    if (rules.maxDecimals != null) {
        validators.push({
            execute: validateMaxDecimals,
            condition: rules.maxDecimals
        });
    }
    return validators;
}
export function getDateValidators(rules) {
    //console.log('getting date validators');
    const validators = [];
    if (rules.isRequired) {
        validators.push(getIsRequiredValidator());
    }
    validators.push({
        execute: validateIsDate
    });
    if (rules.maxValue instanceof Date) {
        validators.push({
            execute: validateMaxDate,
            condition: rules.maxValue
        });
    }
    if (rules.minValue instanceof Date) {
        validators.push({
            execute: validateMinDate,
            condition: rules.minValue
        });
    }
    if (rules.weekdaysOnly) {
        validators.push({
            execute: validateWeekdaysOnly
        });
    }
    return validators;
}
export function getTimeValidators(rules) {
    //console.log('getting date validators');
    const validators = [];
    if (rules.isRequired) {
        validators.push(getIsRequiredValidator());
    }
    validators.push({
        execute: validateIsTime
    });
    if (rules.maxValue != null && typeof rules.maxValue.getHours === 'function' && typeof rules.maxValue.getMinutes === 'function') {
        validators.push({
            execute: validateMaxTime,
            condition: rules.maxValue
        });
    }
    if (rules.minValue != null && typeof rules.minValue.getHours === 'function' && typeof rules.minValue.getMinutes === 'function') {
        validators.push({
            execute: validateMinTime,
            condition: rules.minValue
        });
    }
    return validators;
}
/**
 * There are times when we need to combined some custom validation functions into one so this function will take care of that.
 * This should NOT be used very often and before you do, make sure to ask yourself if there is a way to use an array of validators
 * instead.
 *
 * It specifically allows undefined values in the array so option inputs can be combined more easily.
 *
 * @param validationFunctions: Multiple validation functions
 * @returns A single validation function that calls all of the ones passed in.
 */
export function combineValidationFunctions(...validationFunctions) {
    return function (value, condition, context) {
        for (const currentFunction of validationFunctions) {
            if (currentFunction == null) {
                continue;
            }
            const result = currentFunction(value, condition, context);
            if (!result.isValid) {
                return result;
            }
        }
        return { isValid: true };
    };
}
